#!/bin/sh
# Generated by build-installer.py. Offline, read-only Proxy Monitor v15.
set -eu
PATH=/usr/sbin:/usr/bin:/sbin:/bin
export PATH
umask 077
[ "$(id -u)" -eq 0 ] || { echo 'ERROR: root required'; exit 1; }
case "${1:-}" in ''|--mobile-api) ;; *) echo 'Usage: installer [--mobile-api]'; exit 1 ;; esac
command -v ucode >/dev/null || { echo 'ERROR: ucode missing'; exit 1; }
[ -x /bin/ubus ] && [ -x /etc/init.d/rpcd ] || { echo 'ERROR: rpcd/ubus missing'; exit 1; }
ucode -e "import * as fs from 'fs'; exit(fs.stat('/') ? 0 : 1);"
LOCK=/tmp/proxy-monitor-v15-install.lock
check_parents() {
    d=$(dirname "$1")
    while [ "$d" != / ]; do
        [ ! -L "$d" ] || { echo "ERROR: symlink parent $d"; return 1; }
        d=$(dirname "$d")
    done
}
check_parents /tmp/proxy-monitor-v15-install.lock
check_parents /root/recovery/snapshot
mkdir "$LOCK" 2>/dev/null || { echo 'ERROR: installation lock exists'; exit 1; }
B=''
MUTATED=0
COMMITTED=0
cleanup() {
    rc=$?
    trap - EXIT HUP INT TERM
    if [ "$MUTATED" = 1 ] && [ "$COMMITTED" = 0 ]; then
        echo 'ERROR: deployment failed; restoring snapshot'
        sh "$B/rollback.sh" --held-lock || echo "ERROR: automatic restore incomplete; run $B/rollback.sh"
    fi
    rmdir "$LOCK" 2>/dev/null || true
    exit "$rc"
}
trap cleanup EXIT
trap 'exit 1' HUP INT TERM
mkdir -p /root/recovery
B=$(mktemp -d /root/recovery/proxy-monitor-v15-XXXXXXXX)
mkdir -p "$B/originals" "$B/stage"
cat > "$B/manifest" <<'MANIFEST'
/usr/libexec/proxy-monitor-status
/www/luci-static/resources/view/services/proxy-monitor.js
/usr/libexec/rpcd/proxy-monitor
/usr/share/luci/menu.d/luci-app-proxy-monitor.json
/usr/share/rpcd/acl.d/luci-app-proxy-monitor.json
/www/cgi-bin/proxy-monitor-mobile
/etc/proxy-monitor/mobile-token
/www/luci-static/resources/view/status/include/00_proxy-monitor.js
/www/luci-static/resources/view/status/include/75_proxy-monitor.js
/usr/libexec/proxy-monitor-traffic
MANIFEST
while IFS= read -r p; do
    check_parents "$p"
    [ ! -L "$p" ] || { echo "ERROR: symlink destination $p"; exit 1; }
    [ ! -e "$p" ] || [ -f "$p" ] || { echo "ERROR: non-file destination $p"; exit 1; }
    if [ -f "$p" ]; then
        mkdir -p "$B/originals$(dirname "$p")"
        cp -p "$p" "$B/originals$p"
    fi
done < "$B/manifest"
cat > "$B/rollback.sh" <<'ROLLBACK'
#!/bin/sh
set -eu
PATH=/usr/sbin:/usr/bin:/sbin:/bin
export PATH
B="$(CDPATH= cd "$(dirname "$0")" && pwd)"
LOCK=/tmp/proxy-monitor-v15-install.lock
if [ "${1:-}" != --held-lock ]; then
    mkdir "$LOCK" 2>/dev/null || { echo 'ERROR: installation/rollback lock exists'; exit 1; }
    trap 'rmdir "$LOCK" 2>/dev/null || true' EXIT
fi
check_parents() {
    d=$(dirname "$1")
    while [ "$d" != / ]; do
        [ ! -L "$d" ] || { echo "ERROR: symlink parent $d"; return 1; }
        d=$(dirname "$d")
    done
}
atomic_copy() {
    tmp=$(mktemp "$2.pm-v15-XXXXXXXX")
    if ! cp -p "$1" "$tmp" || ! mv -f "$tmp" "$2"; then
        rm -f "$tmp"; return 1
    fi
}
while IFS= read -r p; do
    check_parents "$p"
    [ ! -L "$p" ] || { echo "ERROR: refuse symlink $p"; exit 1; }
    if [ -f "$B/originals$p" ]; then
        mkdir -p "$(dirname "$p")"
        atomic_copy "$B/originals$p" "$p"
    else rm -f "$p"; fi
done < "$B/manifest"
rm -f /tmp/luci-indexcache
rm -rf /tmp/luci-modulecache
/etc/init.d/rpcd restart
echo "Proxy Monitor restored: $B"
ROLLBACK
chmod 0700 "$B/rollback.sh"
mkdir -p "$B/stage/usr/libexec"
cat > "$B/stage/usr/libexec/proxy-monitor-status" <<'UCODE'
#!/usr/bin/ucode
'use strict';
import * as fs from 'fs';

// Only fixed local commands. UCI values are never shell arguments.
function command(cmd) {
    let p = fs.popen(cmd, 'r');
    if (!p) return '';
    let out = p.read(262144) || '';
    let rc = p.close();
    return rc == 0 ? trim(out) : '';
}
function read(path, limit) {
    let s = fs.stat(path);
    if (!s || s.type != 'file' || s.size > (limit || 4096)) return '';
    let f = fs.open(path, 'r');
    if (!f) return '';
    let out = f.read(limit || 4096) || '';
    f.close();
    return trim(out);
}
function object(raw) {
    try { let d = json(raw); return type(d) == 'object' ? d : {}; }
    catch (e) { return {}; }
}
function id(s) { return type(s) == 'string' && match(s, /^[A-Za-z0-9_]{1,64}$/) ? s : ''; }
function label(s, fallback) {
    // Remarks are display metadata, never URLs, credentials or configuration dumps.
    if (type(s) != 'string' || length(s) > 96 || match(s, /[[:cntrl:]:\/@=]/)) return fallback;
    return s || fallback;
}
function enum_value(s, allowed) { return index(allowed, s) >= 0 ? s : 'UNKNOWN'; }
function flag(s) { return s == '1' ? true : s == '0' ? false : null; }
function number(s) {
    return type(s) == 'string' && match(s, /^[0-9]{1,8}$/) ? int(s) : null;
}

// Stable rpcd UCI interface, no generated engine configuration or subscription reads.
let conf = object(command("/bin/ubus call uci get '{\"config\":\"passwall2\"}' 2>/dev/null"));
let values = type(conf.values) == 'object' ? conf.values : {};
let global = {};
let apps = {};
for (let key, val in values)
    if (type(val) == 'object' && val['.type'] == 'global' &&
        (global['.index'] == null || val['.index'] < global['.index'])) global = val;
for (let key, val in values)
    if (type(val) == 'object' && val['.type'] == 'global_app' &&
        (apps['.index'] == null || val['.index'] < apps['.index'])) apps = val;
let selected = id(global.node) || id(global.tcp_node);
let node = type(values[selected]) == 'object' ? values[selected] : {};
let protocol = enum_value(node.protocol, ['_shunt', '_balancing', '_iface', 'vless', 'vmess', 'trojan', 'shadowsocks', 'socks', 'http', 'hysteria2', 'tuic', 'wireguard']);
let candidate = protocol == '_shunt' ? id(node.default_node) : protocol == '_balancing' ? selected : '';
let balancer = type(values[candidate]) == 'object' && values[candidate].protocol == '_balancing' ? candidate : '';
let balance = balancer ? values[balancer] : {};
